window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ce096c4ef6bfdd42"]={"versions": [{"id": "FIG-ce096c4ef6bfdd42", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm für die Wrapper-Funktion <code>E2EPW_Write1</code> im Kontext der AUTOSAR E2E Library (End-to-End Communication Protection Library). Das Diagramm spezifiziert den kontrollierten Ablauf zur E2E-Absicherung von Anwendungsdaten vor bzw. während der Weitergabe an die AUTOSAR Runtime Environment (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Funktionen:</strong></li>\n<li><code>WriteVariable</code>: Ausführungskontext bzw. Scope der Sende-Wrapper-Funktion.</li>\n<li><code>E2E_PXXProtect</code>: Generische E2E-Profil-Schutzfunktion (z. B. Profil 1/2/4/5/6/7/11/22 etc.).</li>\n<li>Serialisierungsroutine (<code>SerializeAppDataEl</code>).</li>\n<li><strong>Variablen & Parameter:</strong></li>\n<li><code>retRteWrite</code>: Rückgabestatus des RTE-Schreibzugriffs (initialisiert mit <code>RTE_E_OK</code>).</li>\n<li><code>retE2EProtect</code>: Rückgabestatus der Profil-Schutzfunktion (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>plausibilityChecks</code>: Status interner Plausibilitätsprüfungen (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>AppDataEl</code>: Zeiger bzw. Referenz auf das zu übertragende Anwendungsdatenelement.</li>\n<li><code>Data</code>: Puffer in I-PDU-Darstellung für die E2E-Verarbeitung.</li>\n<li><code>Config1</code>, <code>State1</code>: Konfigurations- und Zustandsstrukturen des jeweiligen E2E-Profils.</li>\n<li><code>ret</code>: Zusammengesetzter 32-Bit-Gesamtrückgabewert.</li>\n<li><strong>Konstanten & Fehlercodes:</strong></li>\n<li><code>RTE_E_OK</code>, <code>E2E_E_OK</code>, <code>E2E_E_INPUTERR_NULL</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start der Aktivität; Initialisierung der Variablen <code>retRteWrite = RTE_E_OK</code>, <code>retE2EProtect = E2E_E_OK</code> und <code>plausibilityChecks = E2E_E_OK</code>.</li>\n<li><strong>Eingangsprüfung:</strong> Verzweigung anhand der Bedingung <code>AppDataEl == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>; direkter Übergang zum Zusammenführen des Kontrollflusses vor der Ergebnisbildung.</li>\n<li><code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die I-PDU-Darstellung <code>Data</code> (sofern es sich um ein komplexes Datenelement handelt), andernfalls direktes Kopieren des Byte-Arrays nach <code>Data</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>E2E-Schutz:</strong> Aufruf von <code>retE2EProtect = E2E_PXXProtect(Config1, State1, Data)</code>.</li>\n<li><strong>Erfolgsprüfung Schutz:</strong> Verzweigung anhand <code>retE2EProtect == E2E_E_OK</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Zurückschreiben von CRC und Counter aus <code>Data</code> in <code>AppDataEl</code>.</li>\n<li><code>[FALSE]</code>: Überspringen des Zurückschreibens.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisbildung & Abschluss:</strong> Zusammenführung aller Pfade; Bitweises Kombinieren des Gesamtrückgabewerts über <code>ret = retRteWrite | (retE2EProtect &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16)</code>; Rückgabe von <code>ret</code> an das Aktivitätsende.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normativ verbindliche Verhalten des E2E-Protection-Wrappers beim Senden (<code>Write</code>):</p>\n<ul class=\"fig-list\">\n<li>Null-Pointer-Prüfung (<code>E2E_E_INPUTERR_NULL</code>) schützt vor Null-Referenzierungen vor der Datenverarbeitung.</li>\n<li>CRC und Sequenzzähler dürfen nur bei erfolgreicher E2E-Berechnung (<code>retE2EProtect == E2E_E_OK</code>) in die Anwendungsdatenstruktur zurückgespiegelt werden.</li>\n<li>Fehlercodes werden in einem bitweisen Schema kodiert (Byte 0: RTE-Status, Byte 1: E2E-Protect-Status, Byte 2: Plausibilitäts-Status), was von aufrufenden Software-Komponenten bei der Auswertung des Rückgabewertes zwingend zu berücksichtigen ist.</li>\n</ul>"}, {"id": "FIG-81a71e5f7669501e", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm für die Wrapper-Funktion <code>E2EPW_Write1</code> im Kontext der AUTOSAR E2E Library (End-to-End Communication Protection Library). Das Diagramm spezifiziert den kontrollierten Ablauf zur E2E-Absicherung von Anwendungsdaten vor bzw. während der Weitergabe an die AUTOSAR Runtime Environment (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Funktionen:</strong></li>\n<li><code>WriteVariable</code>: Ausführungskontext bzw. Scope der Sende-Wrapper-Funktion.</li>\n<li><code>E2E_PXXProtect</code>: Generische E2E-Profil-Schutzfunktion (z. B. Profil 1/2/4/5/6/7/11/22 etc.).</li>\n<li>Serialisierungsroutine (<code>SerializeAppDataEl</code>).</li>\n<li><strong>Variablen & Parameter:</strong></li>\n<li><code>retRteWrite</code>: Rückgabestatus des RTE-Schreibzugriffs (initialisiert mit <code>RTE_E_OK</code>).</li>\n<li><code>retE2EProtect</code>: Rückgabestatus der Profil-Schutzfunktion (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>plausibilityChecks</code>: Status interner Plausibilitätsprüfungen (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>AppDataEl</code>: Zeiger bzw. Referenz auf das zu übertragende Anwendungsdatenelement.</li>\n<li><code>Data</code>: Puffer in I-PDU-Darstellung für die E2E-Verarbeitung.</li>\n<li><code>Config1</code>, <code>State1</code>: Konfigurations- und Zustandsstrukturen des jeweiligen E2E-Profils.</li>\n<li><code>ret</code>: Zusammengesetzter 32-Bit-Gesamtrückgabewert.</li>\n<li><strong>Konstanten & Fehlercodes:</strong></li>\n<li><code>RTE_E_OK</code>, <code>E2E_E_OK</code>, <code>E2E_E_INPUTERR_NULL</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start der Aktivität; Initialisierung der Variablen <code>retRteWrite = RTE_E_OK</code>, <code>retE2EProtect = E2E_E_OK</code> und <code>plausibilityChecks = E2E_E_OK</code>.</li>\n<li><strong>Eingangsprüfung:</strong> Verzweigung anhand der Bedingung <code>AppDataEl == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>; direkter Übergang zum Zusammenführen des Kontrollflusses vor der Ergebnisbildung.</li>\n<li><code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die I-PDU-Darstellung <code>Data</code> (sofern es sich um ein komplexes Datenelement handelt), andernfalls direktes Kopieren des Byte-Arrays nach <code>Data</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>E2E-Schutz:</strong> Aufruf von <code>retE2EProtect = E2E_PXXProtect(Config1, State1, Data)</code>.</li>\n<li><strong>Erfolgsprüfung Schutz:</strong> Verzweigung anhand <code>retE2EProtect == E2E_E_OK</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Zurückschreiben von CRC und Counter aus <code>Data</code> in <code>AppDataEl</code>.</li>\n<li><code>[FALSE]</code>: Überspringen des Zurückschreibens.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisbildung & Abschluss:</strong> Zusammenführung aller Pfade; Bitweises Kombinieren des Gesamtrückgabewerts über <code>ret = retRteWrite | (retE2EProtect &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16)</code>; Rückgabe von <code>ret</code> an das Aktivitätsende.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normativ verbindliche Verhalten des E2E-Protection-Wrappers beim Senden (<code>Write</code>):</p>\n<ul class=\"fig-list\">\n<li>Null-Pointer-Prüfung (<code>E2E_E_INPUTERR_NULL</code>) schützt vor Null-Referenzierungen vor der Datenverarbeitung.</li>\n<li>CRC und Sequenzzähler dürfen nur bei erfolgreicher E2E-Berechnung (<code>retE2EProtect == E2E_E_OK</code>) in die Anwendungsdatenstruktur zurückgespiegelt werden.</li>\n<li>Fehlercodes werden in einem bitweisen Schema kodiert (Byte 0: RTE-Status, Byte 1: E2E-Protect-Status, Byte 2: Plausibilitäts-Status), was von aufrufenden Software-Komponenten bei der Auswertung des Rückgabewertes zwingend zu berücksichtigen ist.</li>\n</ul>"}], "trans": [{"from": "FIG-ce096c4ef6bfdd42", "to": "FIG-81a71e5f7669501e", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
